<script setup>
import { ref,onMounted,onBeforeUnmount,computed } from 'vue'
import { api } from '../api'
import { useRoute } from 'vue-router'
const planOnly=useRoute().meta.timerKind==='plan'
import { accountEpoch } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
import ConfirmDialog from './ui/ConfirmDialog.vue'
const durationPlan=ref(null),durationMinutes=ref(25)
const data=ref(null),trial=ref(null),phase=ref(null),plans=ref([]),error=ref(''),mode=ref('gentle'),ack=ref(false),seconds=ref(''),explanation=ref(''),now=ref(Date.now()),writes=useWorkflowWrite('timers'),epoch=accountEpoch
const kindLabel={plan:'计划',base:'基础娱乐',voucher:'金币券娱乐'}
const edits=ref({})
function editOf(row){return edits.value[row.id]||(edits.value[row.id]={open:false,explanation:'',seconds:''})}
function toggleEdit(row){const item=editOf(row);item.open=!item.open}
function humanSeconds(value){const total=Math.max(0,Math.round(Number(value)||0));const minutes=Math.floor(total/60);return minutes?`${minutes} 分 ${total%60} 秒`:`${total} 秒`}
let alive=true,clock=null,offset=0
const elapsed=computed(()=>{const row=data.value?.active;if(!row)return 0;return row.intervals.reduce((sum,i)=>sum+Math.max(0,((i.end?Date.parse(i.end):now.value+offset)-Date.parse(i.start))/1000),0)})
// v1.13 TM：只加展示用的派生值，计时/宽限/扣费逻辑不动
const remaining=computed(()=>Math.max(0,(data.value?.active?.limit_seconds||0)-elapsed.value))
const ringPct=computed(()=>{const limit=data.value?.active?.limit_seconds||0;return limit?Math.min(100,Math.max(0,elapsed.value*100/limit)):0})
const stateLabel=computed(()=>({running:'计时中',paused:'已暂停',review:'待确认结束'}[data.value?.active?.state]||''))
const activeName=computed(()=>data.value?.active?.contract?.plan_snapshot?.name||'')
function clockText(sec){const s=Math.max(0,Math.round(Number(sec)||0));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(v=>String(v).padStart(2,'0')).join(':')}
async function load(){try{const [result,daily,schedules,stage]=await Promise.all([api.flow('/timers'),api.flow('/trial'),api.flow('/projects'),api.flow('/phase')]);if(!alive||epoch!==accountEpoch)return;if(data.value?.active?.id!==result.active?.id){seconds.value='';explanation.value=result.active?.explanation||''}data.value=result;trial.value=daily;plans.value=schedules.items.filter(p=>p.effective?.enabled&&!p.effective?.removed).map(p=>({...p,source_type:p.origin,timing:{name:p.effective.name,enabled:p.effective.enabled,planned_minutes:Object.hasOwn(p.effective.rule,'planned_minutes')?p.effective.rule.planned_minutes:p.origin==='plan'?30:null}}));phase.value=stage.phase;offset=Date.parse(result.server_now)-Date.now()}catch(e){error.value=e.message}}
async function act(path,body={}){try{await writes.send(path,body);await load();error.value=''}catch(e){error.value=e.message}}
async function start(kind,source_id,plan=null,minutes=null){if(plan&&plan.timing.planned_minutes==null&&minutes==null){durationPlan.value=plan;durationMinutes.value=25;return}await act('/timers',{kind,source_id,mode:mode.value,acknowledge_penalty:ack.value,...(plan?{source_version:plan.version,source_type:plan.source_type,planned_minutes:minutes??plan.timing.planned_minutes}:{})})}
async function confirmDuration(){if(!Number.isInteger(durationMinutes.value)||durationMinutes.value<1||durationMinutes.value>1440){error.value='请填1～1440的整数分钟。';return}const plan=durationPlan.value;await start('plan',plan.id,plan,durationMinutes.value);if(!error.value)durationPlan.value=null}
async function update(action,row=data.value?.active,src=null){if(!row)return;const note=src?src.explanation:explanation.value,raw=src?src.seconds:seconds.value;await act('/timers/'+row.id+'/'+action,{expected_version:row.version,...(['end-preview','explain'].includes(action)?{explanation:note,...(raw!==''&&action==='end-preview'?{actual_seconds:Number(raw)}:{})}:{})})}
function visibility(){if(!document.hidden)load()}
onMounted(()=>{load();clock=setInterval(()=>now.value=Date.now(),1000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{alive=false;clearInterval(clock);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><div class="reading-page"><PageHeader :title="planOnly?'计划计时':'娱乐计时'" description="按时间差显示用量；离线不自动认定违规，回来可以核对。"/><p v-if="error" class="error" role="alert">{{ error }}</p><button v-if="writes.pending.value" class="btn" @click="act(writes.pending.value.path,writes.pending.value.body)">恢复上次请求</button><section v-if="data?.active" class="card timer-card"><div class="timer-head"><span class="tag">{{ stateLabel }}</span><span v-if="activeName" class="muted">{{ activeName }}</span></div><p class="timer-quota">本次可用 {{ humanSeconds(data.active.limit_seconds) }}</p><div class="timer-ring" :style="{ '--pct': ringPct }"><div class="timer-ring-inner"><strong>{{ clockText(remaining) }}</strong><span>剩余</span></div></div><p class="timer-used">本次已用 {{ clockText(elapsed) }}</p><p v-if="elapsed>=data.active.limit_seconds" role="status" class="muted">约定时长已到，可以结束并核对。娱乐宽限3分钟；实际停止时间由你确认，不凭离线自动罚款。</p><button v-if="data.active.state==='running'" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('pause')">暂停</button><button v-if="data.active.state==='paused'" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('resume')">继续</button><details><summary>确认仍在用</summary><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="update('sync')">确认仍在使用并同步</button></details><details><summary>意外关闭 / 补充说明</summary><label>说明情况（先保存，可选分析）<textarea v-model="explanation" maxlength="4000"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!explanation.trim()" @click="update('explain')">保存说明</button><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!data.active.explanation" @click="update('analyze-explanation')">仅分析本次说明</button><p v-if="data.active.analysis">{{ data.active.analysis.summary }} · 建议实际 {{ humanSeconds(data.active.analysis.suggested_seconds) }}（仍须你核对）</p></details><details><summary>调整实际用量（可选）</summary><label>核对实际使用秒数（可空）<input type="number" min="0" v-model="seconds"/></label></details><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('end-preview')">结束并查看核对预览</button><div v-if="data.active.preview"><p v-if="data.active.preview.offline_interval">存在未同步区间，请核对实际停止时间；不会仅据离线自动罚款。</p><p>实际 {{ humanSeconds(data.active.preview.actual_seconds) }} · 处罚 {{ data.active.preview.penalty_charged }} 币 · 守时 {{ data.active.preview.ontime_awarded }} 币 · 金币变动 {{ data.active.preview.coin_delta }}</p><button class="btn primary" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('confirm')">确认实际用量与结算</button></div></section><section v-else class="card"><h2>开始一次计时</h2><label v-if="!planOnly">娱乐约定<select v-model="mode"><option value="gentle">温和提醒，不扣币</option><option v-if="phase?.payload.accepted_mode==='strong'" value="strong">已接受加强：每5分钟4币，单次20／每日30</option><option value="strict">严格：宽限后每5分钟2币，单次10／每日20上限</option></select></label><label v-if="!planOnly&&mode!=='gentle'"><input type="checkbox" v-model="ack"/>我在开始前同意本次处罚规则</label><button v-if="!planOnly&&trial?.daily&&trial.daily.base_seconds>trial.daily.used_seconds" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="start('base',trial.daily.id)">使用当天基础娱乐</button><article v-for="row in (planOnly?[]:data?.vouchers)" :key="row.redemption.id"><p>金币券 #{{ row.redemption.id }} · 剩余 {{ humanSeconds((row.allowance?.total_seconds??row.redemption.duration_seconds)-(row.allowance?.used_seconds||0)) }}</p><button class="btn" :disabled="writes.busy.value||row.redemption.status==='fulfilled'" @click="start('voucher',row.redemption.id)">使用这张券（本次重新计时）</button></article><details v-if="planOnly" open><summary>有时长的行动计划</summary><button v-for="plan in plans.filter(p=>p.category==='plan'&&p.timing?.enabled&&p.timing?.planned_minutes>0)" :key="plan.key" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="start('plan',plan.id,plan)">{{ plan.timing?.name||plan.name }} · {{ plan.timing.planned_minutes==null?'开始前填写时长':plan.timing.planned_minutes+' 分钟' }}</button></details></section><details><summary>历史计时与更正</summary><article v-for="row in data?.items.filter(r=>r.state==='ended')" :key="row.id"><p>{{ row.local_date }} · {{ kindLabel[row.kind]||row.kind }} · {{ humanSeconds(row.settlement?.actual_seconds) }} <button class="text-button" @click="toggleEdit(row)">{{ editOf(row).open?'收起':'更正' }}</button></p><div v-if="editOf(row).open"><label>说明<textarea v-model="editOf(row).explanation"/></label><label>更正实际秒数<input type="number" min="0" v-model="editOf(row).seconds"/></label><button class="btn" @click="update('end-preview',row,editOf(row))">预览更正</button><p v-if="row.preview">金币差额 {{ row.preview.coin_delta }}；历史流水保留。<button class="btn" @click="update('confirm',row,editOf(row))">确认更正</button></p></div></article></details><ConfirmDialog :open="!!durationPlan" title="这次准备投入多久？" confirm-label="开始本次计时" :busy="writes.busy.value" @cancel="durationPlan=null" @confirm="confirmDuration"><p>仅用于这次会话，项目本身保持未设固定时长。</p><label>本次分钟<input type="number" min="1" max="1440" v-model.number="durationMinutes"/></label><p v-if="error" class="error">{{ error }}</p></ConfirmDialog></div></template>
